'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var randu = require( '@stdlib/random/base/randu' );
var discreteUniform = require( '@stdlib/random/base/discrete-uniform' );
var ndarray = require( '@stdlib/ndarray/ctor' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var isMatrixLike = require( '@stdlib/assert/is-matrix-like' );
var isVectorLike = require( '@stdlib/assert/is-vector-like' );
var pkg = require( './../package.json' ).name;
var incrlvq = require( './../lib' );


// MAIN //

bench( pkg+'::options:learningRate', function benchmark( b ) {
	var lr;
	var f;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		lr = randu();
		f = incrlvq({
			'learningRate': lr
		});
		if ( typeof f !== 'function' ) {
			b.fail( 'should return a function' );
		}
	}
	b.toc();
	if ( typeof f !== 'function' ) {
		b.fail( 'should return a function' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+'::prototypes,labels', function benchmark( b ) {
	var labelBuffer;
	var protoBuffer;
	var prototypes;
	var strides;
	var labels;
	var shape;
	var f;
	var i;

	protoBuffer = new Float64Array( [ 0.0, 0.0, 1.0, 1.0 ] );
	shape = [ 2, 2 ];
	strides = [ 2, 1 ];
	prototypes = ndarray( 'float64', protoBuffer, shape, strides, 0, 'row-major' );

	labelBuffer = new Int32Array( [ 0, 1 ] );
	shape = [ 2 ];
	strides = [ 1 ];
	labels = ndarray( 'int32', labelBuffer, shape, strides, 0, 'row-major' );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		f = incrlvq( prototypes, labels );
		if ( typeof f !== 'function' ) {
			b.fail( 'should return a function' );
		}
	}
	b.toc();
	if ( typeof f !== 'function' ) {
		b.fail( 'should return a function' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

