bench( pkg+'::accumulator:predict', function benchmark( b ) {
	var labelBuffer;
	var protoBuffer;
	var prototypes;
	var strides;
	var labels;
	var buffer;
	var shape;
	var vec;
	var mat;
	var acc;
	var out;
	var y;
	var i;

	protoBuffer = new Float64Array( [ 0.0, 0.0, 1.0, 1.0 ] );
	shape = [ 2, 2 ];
	strides = [ 2, 1 ];
	prototypes = ndarray( 'float64', protoBuffer, shape, strides, 0, 'row-major' );

	labelBuffer = new Int32Array( [ 0, 1 ] );
	shape = [ 2 ];
	strides = [ 1 ];
	labels = ndarray( 'int32', labelBuffer, shape, strides, 0, 'row-major' );

	buffer = new Float64Array( 2 );
	shape = [ 2 ];
	strides = [ 1 ];
	vec = ndarray( 'float64', buffer, shape, strides, 0, 'row-major' );

	buffer = new Float64Array( 2 );
	shape = [ 1, 2 ];
	strides = [ 2, 1 ];
	mat = ndarray( 'float64', buffer, shape, strides, 0, 'row-major' );

	acc = incrlvq( prototypes, labels );

	// Update the accumulator, providing enough data for the accumulator to compute prototypes...
	for ( i = 0; i < 1000; i++ ) {
		vec.set( 0, randu() );
		vec.set( 1, randu() );
		y = discreteUniform( 0, 1 );
		acc( vec, y );
	}

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		mat.set( 0, 0, randu() );
		mat.set( 0, 1, randu() );
		out = acc.predict( mat );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isVectorLike( out ) ) {
		b.fail( 'should be a vector' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+'::accumulator,reuse:predict', function benchmark( b ) {
	var labelBuffer;
	var protoBuffer;
	var prototypes;
	var strides;
	var labels;
	var buffer;
	var shape;
	var vec;
	var mat;
	var acc;
	var out;
	var o;
	var y;
	var i;

	protoBuffer = new Float64Array( [ 0.0, 0.0, 1.0, 1.0 ] );
	shape = [ 2, 2 ];
	strides = [ 2, 1 ];
	prototypes = ndarray( 'float64', protoBuffer, shape, strides, 0, 'row-major' );

	labelBuffer = new Int32Array( [ 0, 1 ] );
	shape = [ 2 ];
	strides = [ 1 ];
	labels = ndarray( 'int32', labelBuffer, shape, strides, 0, 'row-major' );

	buffer = new Float64Array( 2 );
	shape = [ 2 ];
	strides = [ 1 ];
	vec = ndarray( 'float64', buffer, shape, strides, 0, 'row-major' );

	buffer = new Float64Array( 2 );
	shape = [ 1, 2 ];
	strides = [ 2, 1 ];
	mat = ndarray( 'float64', buffer, shape, strides, 0, 'row-major' );

	buffer = new Int32Array( 1 );
	shape = [ 1 ];
	strides = [ 1 ];
	out = ndarray( 'int32', buffer, shape, strides, 0, 'row-major' );

	acc = incrlvq( prototypes, labels );

	// Update the accumulator, providing enough data for the accumulator to compute prototypes...
	for ( i = 0; i < 1000; i++ ) {
		vec.set( 0, randu() );
		vec.set( 1, randu() );
		y = discreteUniform( 0, 1 );
		acc( vec, y );
	}

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		mat.set( 0, 0, randu() );
		mat.set( 0, 1, randu() );
		o = acc.predict( out, mat );
		if ( typeof o !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isVectorLike( o ) ) {
		b.fail( 'should be a vector' );
	}
	if ( o !== out ) {
		b.fail( 'should return output vector' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+'::accumulator:predict.size=10', function benchmark( b ) {
	var protoBuffer;
	var labelBuffer;
	var prototypes;
	var strides;
	var labels;
	var buffer;
	var shape;
	var vec;
	var mat;
	var acc;
	var out;
	var y;
	var i;
	var j;

	protoBuffer = new Float64Array( [ 0.0, 0.0, 1.0, 1.0 ] );
	shape = [ 2, 2 ];
	strides = [ 2, 1 ];
	prototypes = ndarray( 'float64', protoBuffer, shape, strides, 0, 'row-major' );

	labelBuffer = new Int32Array( [ 0, 1 ] );
	shape = [ 2 ];
	strides = [ 1 ];
	labels = ndarray( 'int32', labelBuffer, shape, strides, 0, 'row-major' );

	buffer = new Float64Array( 2 );
	shape = [ 2 ];
	strides = [ 1 ];
	vec = ndarray( 'float64', buffer, shape, strides, 0, 'row-major' );

	buffer = new Float64Array( 20 );
	shape = [ 10, 2 ];
	strides = [ 2, 1 ];
	mat = ndarray( 'float64', buffer, shape, strides, 0, 'row-major' );

	acc = incrlvq( prototypes, labels );

	// Update the accumulator, providing enough data for the accumulator to compute prototypes...
	for ( i = 0; i < 100; i++ ) {
		vec.set( 0, randu() );
		vec.set( 1, randu() );
		y = discreteUniform( 0, 1 );
		acc( vec, y );
	}

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		for ( j = 0; j < 10; j++ ) {
			mat.set( j, 0, randu() );
			mat.set( j, 1, randu() );
		}
		out = acc.predict( mat );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isVectorLike( out ) ) {
		b.fail( 'should be a vector' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
